2	import {
3	  MATCH_ROOM,
4	  MessageType,
5	  normalizeMatchCode,
6	  PROTOCOL_VERSION,
7	  type InputMessage,
8	} from "@pirate-sea-race/protocol";
9	import type { MatchStateSchema } from "@pirate-sea-race/server/schema";
10	
11	export interface HeadlessClientOptions {
12	  /** Override the protocol version sent on join, to exercise the version check. */
13	  readonly protocolVersion?: number;
14	}
15	
16	export interface ShipView {
17	  readonly id: string;
18	  readonly slot: number;
19	  readonly x: number;
20	  readonly y: number;
21	}
22	
23	export interface Movement {
24	  readonly moveX: number;
25	  readonly moveY: number;
26	  readonly buttons?: number;
27	}
28	
29	/**
30	 * A browserless player: joins a private match through the real Colyseus SDK, decodes the synced state, and sends
31	 * frame-tagged inputs with increasing sequence numbers, exactly as the web client does.
32	 */
33	export class HeadlessClient {
34	  private seq = 0;
35	  private open = true;
36	
37	  private constructor(readonly room: Room<unknown, MatchStateSchema>) {
38	    room.onLeave(() => {
39	      this.open = false;
40	    });
41	  }
42	
43	  /** Creates a private match on the server at `endpoint` (for example `http://127.0.0.1:2593`). */
44	  static async create(endpoint: string, options: HeadlessClientOptions = {}): Promise<HeadlessClient> {
45	    const client = new Client(endpoint);
46	    const room = await client.create<MatchStateSchema>(MATCH_ROOM, {
47	      protocolVersion: options.protocolVersion ?? PROTOCOL_VERSION,
48	    });
49	    const headless = new HeadlessClient(room);
50	    await headless.waitFor(() => headless.code !== "" && headless.ship() !== undefined);
51	    return headless;
52	  }
53	
54	  /** Joins the private match with `code` (any case). */
