2	
3	export interface ShipSnapshot {
4	  readonly id: string;
5	  readonly slot: number;
6	  readonly x: number;
7	  readonly y: number;
8	  readonly heading: number;
9	}
10	
11	/** Placeholder ship colours by spawn slot. */
12	const SLOT_COLORS = [0xf4b942, 0xe5484d, 0x46a758, 0xb66ee8, 0xf76b15, 0x3dd6d0, 0xf2f2f2, 0xd6409f] as const;
13	
14	export function slotColor(slot: number): number {
15	  return SLOT_COLORS[slot % SLOT_COLORS.length]!;
16	}
17	
18	export function cssColor(color: number): string {
19	  return `#${color.toString(16).padStart(6, "0")}`;
20	}
21	
22	/**
23	 * The client's picture of the match: the latest decoded server positions (for the HUD) and a snapshot history per
24	 * ship (for interpolated drawing).
25	 */
26	export class MatchView {
27	  private readonly latest = new Map<string, ShipSnapshot>();
28	  private readonly buffers = new Map<string, SnapshotBuffer>();
29	
30	  constructor(readonly selfId: string) {}
31	
32	  ingest(ships: Iterable<ShipSnapshot>, now: number): void {
33	    const seen = new Set<string>();
34	    for (const ship of ships) {
35	      seen.add(ship.id);
36	      this.latest.set(ship.id, { id: ship.id, slot: ship.slot, x: ship.x, y: ship.y, heading: ship.heading });
37	      let buffer = this.buffers.get(ship.id);
38	      if (buffer === undefined) this.buffers.set(ship.id, (buffer = new SnapshotBuffer()));
39	      buffer.push(now, ship.x, ship.y);
40	    }
41	    for (const id of [...this.latest.keys()]) {
42	      if (seen.has(id)) continue;
43	      this.latest.delete(id);
44	      this.buffers.delete(id);
45	    }
46	  }
47	
48	  ships(): ShipSnapshot[] {
49	    return [...this.latest.values()];
50	  }
51	
52	  /** Where to draw a ship at `now`, interpolated INTERPOLATION_DELAY_MS in the past. */
53	  renderPosition(id: string, now: number): { x: number; y: number } | undefined {
54	    return this.buffers.get(id)?.sample(now - INTERPOLATION_DELAY_MS);
55	  }
56	}
